    lanes_exports: {china: 0.04, panama: 0.04, central_america_pacific: 0.03, colombia_pacific: 0.01, ecuador: 0.02, peru: 0.02, mexico_pacific: 0.005, canada_east: 0.002, colombia_caribbean: 0.04, mexico_gulf: 0.005, korea: 0.005}
    lanes_imports: {china: 0.2, panama: 0.01, central_america_pacific: 0.04, colombia_pacific: 0.01, ecuador: 0.03, peru: 0.03, mexico_pacific: 0.005, canada_east: 0.002, colombia_caribbean: 0.04, mexico_gulf: 0.01, korea: 0.02}
    relay_share: 0
    relay_hubs: []
    src: "PortMiami fiscal 2025: 1,115,058 TEU (Miami-Dade County; Research Notes 221); loaded share 80% and export share 45% of loaded are estimates"
    assumption_fields: [exports_teu_yr, imports_teu_yr, reefer_share_exports, reefer_share_imports, lanes_exports, lanes_imports]
  savannah:
    region: us_east
    year: 2025
