    lanes_imports: {china: 0.35, peru: 0.004, ecuador: 0.003, colombia_pacific: 0.002, panama: 0.002, central_america_pacific: 0.003, mexico_pacific: 0.001, canada_east: 0.001, colombia_caribbean: 0.005, mexico_gulf: 0.003, korea: 0.05}
    relay_share: 0
